<?php require __DIR__.'/config.php';header('Content-Type: application/json');header('Cache-Control: no-store');if(empty($_SESSION['username'])){http_response_code(401);exit('{"authenticated":false}');}$k=getenv('MULTIPLAYER_SECRET')?:'';if(strlen($k)<32){http_response_code(503);exit;}$p=rtrim(strtr(base64_encode(json_encode(['username'=>$_SESSION['username'],'exp'=>time()+300])),'+/','-_'),'=');$s=rtrim(strtr(base64_encode(hash_hmac('sha256',$p,$k,true)),'+/','-_'),'=');echo json_encode(['authenticated'=>true,'username'=>$_SESSION['username'],'token'=>$p.'.'.$s]);